import{_ as o,C as s,o as r,c as i,j as t,a,E as d,a7 as c}from"./chunks/framework.C4ZIv4ii.js";const k=JSON.parse('{"title":"Instagram Feed","description":"","frontmatter":{},"headers":[],"relativePath":"guide/instagram-feed.md","filePath":"guide/instagram-feed.md","lastUpdated":1792509062000}'),p={name:"guide/instagram-feed.md"},l={id:"instagram-feed",tabindex:"-1"};function h(g,e,u,m,f,w){const n=s("Badge");return r(),i("div",null,[t("h1",l,[e[0]||(e[0]=a("Instagram Feed ",-1)),d(n,{type:"warning",text:"Pro"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#instagram-feed","aria-label":'Permalink to "Instagram Feed <Badge type="warning" text="Pro" />"'},"​",-1))]),e[3]||(e[3]=c('<p>The <strong>Instagram Feed</strong> builder element shows your latest Instagram posts as a grid or a swipeable row, with your profile picture, follower count and a Follow button. It is an advanced builder element, part of <a href="/falconcms/guide/pro.html">FalconCMS Pro</a>.</p><h2 id="connecting-your-account" tabindex="-1">Connecting your account <a class="header-anchor" href="#connecting-your-account" aria-label="Permalink to &quot;Connecting your account&quot;">​</a></h2><p>Instagram only lets websites read <strong>Business</strong> and <strong>Creator</strong> accounts.</p><ol><li>Switch the account to Business or Creator in the Instagram app: <strong>Settings → Account type</strong> (<a href="https://help.instagram.com/502981923235522" target="_blank" rel="noreferrer">Instagram&#39;s help</a>).</li><li>At <a href="https://developers.facebook.com/apps" target="_blank" rel="noreferrer">developers.facebook.com/apps</a>, create an app of type <em>Business</em> and add the <strong>Instagram</strong> product, choosing <em>API setup with Instagram login</em> (<a href="https://developers.facebook.com/docs/instagram-platform/instagram-api-with-instagram-login/get-started" target="_blank" rel="noreferrer">Meta&#39;s guide</a>).</li><li>Under <em>Generate access tokens</em>, add your Instagram account (accept the tester invitation in the Instagram app if asked) and click <strong>Generate token</strong>.</li><li>In FalconCMS open <strong>Appearance → Customizer → Instagram</strong>, paste the token (it starts with <code>IG</code>) and press <strong>Save Changes</strong>.</li></ol><p>The section then shows the connected account, how many posts are saved and when they were last checked. The token is stored encrypted and renewed every week, so it does not lapse after 60 days.</p><p><strong>Fetch latest posts</strong> gets new posts at once; <strong>Disconnect Instagram</strong> removes the token and the saved posts and pictures.</p><h2 id="how-it-stays-fast" tabindex="-1">How it stays fast <a class="header-anchor" href="#how-it-stays-fast" aria-label="Permalink to &quot;How it stays fast&quot;">​</a></h2><p>Pages never wait for Instagram. The posts are saved on your site and checked for new ones in the background, every hour by default (<strong>Check for new posts every</strong> in the Customizer). The pictures are saved on your site too (<strong>Save pictures on this site</strong>), so they keep working when Instagram&#39;s own picture links expire, and readers&#39; browsers never contact Meta. If Instagram is down or the token stops working, the last saved posts keep showing and the Customizer says what went wrong.</p><p>On a server with a scheduler, <code>falcon:instagram-sync</code> runs hourly; without one, a page that shows the feed fetches new posts after its response has been sent.</p><h2 id="adding-the-element" tabindex="-1">Adding the element <a class="header-anchor" href="#adding-the-element" aria-label="Permalink to &quot;Adding the element&quot;">​</a></h2><p>In the builder, add <strong>Instagram Feed</strong>. The canvas shows your real posts.</p><p><strong>General:</strong> where the pictures come from (the connected account, or pictures you choose), number of posts, grid or carousel, columns per device, picture shape (square, portrait, landscape), spacing, profile header, caption (on hover, below, or hidden), hover effect and how links open.</p><p><strong>Design:</strong> corner radius, overlay and icon colours, caption and username typography, button style and margins.</p><h3 id="a-personal-account" tabindex="-1">A personal account? <a class="header-anchor" href="#a-personal-account" aria-label="Permalink to &quot;A personal account?&quot;">​</a></h3><p>Instagram stopped letting websites read personal accounts in December 2024. Switching to a free <strong>Creator</strong> account takes a minute and keeps your followers and posts. Or, without a token:</p><ul><li><strong>Instagram post links (any public account).</strong> In Instagram, open a post or reel and choose <strong>Share → Copy link</strong>, then add the link under <strong>Post links</strong>. Each post is shown with Instagram&#39;s own embedded card (picture or video, likes, caption if <strong>Caption</strong> is not hidden). The account must be public, new posts are not added by themselves, and Instagram&#39;s script loads on the page. On the builder canvas each post is a stand-in card; the real one appears on the page.</li><li><strong>Pictures I choose.</strong> Add the pictures and links yourself, in the element&#39;s own design.</li></ul><p>For both, type your username for the profile header and the Follow button.</p>',17))])}const b=o(p,[["render",h]]);export{k as __pageData,b as default};
